// Kiểm tra đăng nhập, quyền HR và trạng thái hồ sơ; chọn nhánh xử lý cho từng thao tác của giao diện.
const req = $('Yêu cầu từ cổng HR').first().json;
const auth = $('Xác minh phiên đăng nhập').first().json;
const db = $input.first().json;
const b = req.body || {};
const action = String(b.action || '');
const note = String(b.note || '').trim().slice(0, 2000);
const s = db.settings || {};
const out = (route, extra) => [{ json: { route, action, note, ok: true, ...extra } }];
const fail = (http, message) => out('error', { ok: false, http, message });

if (Number(auth.statusCode) !== 200 || !auth.body || !auth.body.email) return fail(401, 'Phiên đăng nhập đã hết hạn, vui lòng đăng nhập lại.');
if (!db.is_hr) return fail(403, 'Tài khoản này không có quyền vào cổng HR.');

const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const wrap = (title, body) => '<div style="font-family:Arial,sans-serif;color:#243447;line-height:1.65;max-width:680px;margin:auto"><div style="background:#142f4c;color:white;padding:22px 28px"><b style="font-size:22px">ABC Tech</b><br>Phòng Tuyển dụng</div><div style="padding:24px 28px"><h2 style="font-size:20px">' + esc(title) + '</h2>' + body + '<p>Trân trọng,<br><b>Bộ phận Tuyển dụng — ABC Tech</b><br><a href="mailto:whateverholding246@gmail.com">whateverholding246@gmail.com</a></p></div></div>';
const p = v => '<p>' + v + '</p>';
const vn = (d, withTime) => {
  const t = new Date(new Date(d).getTime() + 7 * 3600000), two = n => String(n).padStart(2, '0');
  const day = two(t.getUTCDate()) + '/' + two(t.getUTCMonth() + 1) + '/' + t.getUTCFullYear();
  return withTime ? two(t.getUTCHours()) + ':' + two(t.getUTCMinutes()) + ' ngày ' + day : day;
};
const STATUS = { received: 'AI đang đọc CV', awaiting_hr: 'Chờ HR duyệt', hr_overdue: 'Quá hạn duyệt', on_hold: 'Tạm giữ', awaiting_candidate: 'Chờ ứng viên chọn giờ', needs_scheduling: 'Cần HR xếp lịch', interview_scheduled: 'Đã hẹn phỏng vấn', interviewed: 'Chờ kết quả phỏng vấn', hired: 'Nhận việc', rejected: 'Không phù hợp', withdrawn: 'Ứng viên rút hồ sơ' };
const blocked = c => fail(409, 'Hồ sơ ' + c.candidate_id + ' đang ở bước "' + (STATUS[c.status] || c.status) + '", không làm được thao tác này. Vui lòng tải lại trang.');
// Chữ ký link giống WF2 (dùng chung link_secret) để gọi đúng webhook duyệt đầu việc
function kyLink(id, secret) {
  const t = String(id).toUpperCase() + '|' + String(secret);
  let a = 5381, h = 2166136261;
  for (let i = 0; i < t.length; i++) { a = ((a * 33) ^ t.charCodeAt(i)) >>> 0; h = ((h ^ t.charCodeAt(i)) * 16777619) >>> 0; }
  return (a.toString(36) + h.toString(36)).slice(0, 16);
}

if (action === 'candidate.decide') {
  const c = db.candidate;
  if (!c) return fail(404, 'Không tìm thấy hồ sơ.');
  const decision = String(b.decision || '');
  const label = { invite: 'Mời phỏng vấn', hold: 'Tiếp tục xem xét', reject: 'Chưa phù hợp' }[decision];
  if (!label) return fail(400, 'Quyết định không hợp lệ.');
  // WF1 còn đứng chờ HR duyệt: gửi quyết định vào đúng form chờ, WF1 tự chạy tiếp như khi bấm trong email
  if (c.wait && c.wait.resume_url && ['awaiting_hr', 'hr_overdue'].includes(c.status)) {
    return out('resume', { candidate_id: c.candidate_id, resume_url: c.wait.resume_url, wait_id: c.wait.wait_id, field0: label, field1: note,
      message: { invite: 'Đã mời phỏng vấn ' + c.full_name + '. Hệ thống đang đề xuất khung giờ và gửi thư cho ứng viên.', hold: 'Đã tạm giữ hồ sơ ' + c.full_name + '.', reject: 'Đã đóng hồ sơ ' + c.full_name + ' và gửi thư cảm ơn.' }[decision] });
  }
  if (decision === 'invite') {
    if (!['awaiting_hr', 'hr_overdue', 'on_hold', 'needs_scheduling'].includes(c.status)) return blocked(c);
    return out('invite', { candidate_id: c.candidate_id, message: 'Đã mời phỏng vấn ' + c.full_name + '. Hệ thống đang đề xuất khung giờ và gửi thư cho ứng viên.' });
  }
  if (decision === 'hold') {
    if (!['awaiting_hr', 'hr_overdue', 'needs_scheduling'].includes(c.status)) return blocked(c);
    return out('hold', { candidate_id: c.candidate_id, allowed: ['awaiting_hr', 'hr_overdue', 'needs_scheduling'], message: 'Đã tạm giữ hồ sơ ' + c.full_name + '.' });
  }
  const allowed = ['awaiting_hr', 'hr_overdue', 'on_hold', 'needs_scheduling', 'awaiting_candidate', 'interview_scheduled', 'interviewed'];
  if (!allowed.includes(c.status)) return blocked(c);
  const kind = c.status === 'interviewed' ? 'after' : ['awaiting_candidate', 'needs_scheduling', 'interview_scheduled'].includes(c.status) ? 'cancel' : 'review';
  const job = esc(c.job_title);
  const T = {
    review: ['Kết quả xem xét hồ sơ', 'Cảm ơn bạn đã dành thời gian ứng tuyển vào vị trí ' + job + ' tại ABC Tech. Sau khi xem xét yêu cầu của vị trí và hồ sơ hiện tại, chúng tôi rất tiếc chưa thể mời bạn vào vòng tiếp theo trong đợt tuyển dụng này. Chúng tôi trân trọng sự quan tâm của bạn và chúc bạn sớm tìm được cơ hội phù hợp.'],
    after: ['Kết quả phỏng vấn', 'Cảm ơn bạn đã dành thời gian tham gia buổi phỏng vấn cho vị trí ' + job + ' tại ABC Tech. Sau khi cân nhắc kỹ, chúng tôi rất tiếc chưa thể tiếp tục với hồ sơ của bạn trong đợt tuyển dụng này. Chúng tôi trân trọng sự quan tâm của bạn và chúc bạn sớm tìm được cơ hội phù hợp.'],
    cancel: ['Cập nhật lời mời phỏng vấn', 'ABC Tech xin thông báo lời mời phỏng vấn cho vị trí ' + job + ' đã được huỷ; nếu bạn đã nhận lời mời Google Calendar, lịch đó cũng đã được huỷ. Chúng tôi rất tiếc chưa thể tiếp tục với hồ sơ của bạn trong đợt này và cảm ơn bạn đã quan tâm đến ABC Tech.'],
  }[kind];
  return out('reject', {
    candidate_id: c.candidate_id, email: c.email, allowed, kind,
    calendar_event_id: (c.interview && c.interview.calendar_event_id) || '',
    mail_subject: '[ABC Tech] ' + T[0] + ' — ' + c.job_title + ' | ' + c.candidate_id,
    mail_html: wrap(T[0], p('Chào bạn ' + esc(c.full_name) + ',') + p(T[1]) + p('Mã hồ sơ: ' + esc(c.candidate_id) + '.')),
    log_message: 'Từ cổng HR: đóng hồ sơ ' + c.candidate_id + ' (' + (STATUS[c.status] || c.status) + ')' + (kind === 'cancel' ? ', huỷ lời mời phỏng vấn' : '') + '.',
    message: 'Đã đóng hồ sơ ' + c.full_name + ' và gửi thư cảm ơn' + ((c.interview && c.interview.calendar_event_id) ? ', lịch phỏng vấn đã huỷ.' : '.'),
  });
}

if (action === 'candidate.hire') {
  const c = db.candidate;
  if (!c) return fail(404, 'Không tìm thấy hồ sơ.');
  if (c.status !== 'interviewed') return blocked(c);
  return out('hire', { candidate_id: c.candidate_id, message: c.full_name + ' đã nhận việc. Hệ thống đang tạo hồ sơ nhân viên và checklist onboarding.' });
}

if (action === 'candidate.remind') {
  const c = db.candidate;
  if (!c) return fail(404, 'Không tìm thấy hồ sơ.');
  if (c.status !== 'awaiting_candidate') return blocked(c);
  const hours = Number(s.candidate_choice_hours) || 24;
  const sent = c.invited_at ? new Date(c.invited_at) : new Date();
  const until = new Date(sent.getTime() + hours * 3600000);
  const subject = '[ABC Tech] Mời phỏng vấn — ' + c.job_title + ' | ' + c.candidate_id;
  const body = 'ABC Tech đã gửi lời mời phỏng vấn vị trí ' + esc(c.job_title) + ' ngày ' + vn(sent) + '. Bạn vui lòng mở email "' + esc(subject) + '" và bấm "Chọn lịch phỏng vấn" trước ' + vn(until, true) + '. Nếu không tìm thấy email hoặc các khung giờ chưa phù hợp, bạn chỉ cần trả lời thư này.';
  return out('remind_candidate', {
    candidate_id: c.candidate_id, email: c.email,
    mail_subject: '[ABC Tech] Nhắc chọn lịch phỏng vấn — ' + c.job_title + ' | ' + c.candidate_id,
    mail_html: wrap('Nhắc chọn lịch phỏng vấn', p('Chào bạn ' + esc(c.full_name) + ',') + p(body) + p('Mã hồ sơ: ' + esc(c.candidate_id) + '.')),
    log_message: 'Từ cổng HR: nhắc ' + c.candidate_id + ' chọn giờ phỏng vấn.',
    message: 'Đã gửi thư nhắc ' + c.full_name + ' chọn giờ phỏng vấn.',
  });
}

if (action === 'task.review') {
  const t = db.task;
  if (!t) return fail(404, 'Không tìm thấy đầu việc.');
  if (t.status !== 'submitted') return fail(409, 'Đầu việc ' + t.task_id + ' không còn chờ duyệt. Vui lòng tải lại trang.');
  const decision = String(b.decision || '');
  if (!['approve', 'return'].includes(decision)) return fail(400, 'Quyết định không hợp lệ.');
  if (decision === 'return' && !note) return fail(400, 'Cần ghi nhận xét khi trả lại đầu việc.');
  const url = String(s.webhook_base || '').replace(/\/+$/, '') + '/hr-duyet-pg?t=' + encodeURIComponent(t.task_id) + '&k=' + kyLink(t.task_id, s.link_secret)
    + '&act=' + (decision === 'approve' ? 'approve' : 'reject') + '&note=' + encodeURIComponent(note);
  return out('task_review', { task_id: t.task_id, review_url: url, expect: decision === 'approve' ? 'done' : 'in_progress' });
}

if (action === 'employee.remind') {
  const e = db.employee;
  if (!e) return fail(404, 'Không tìm thấy nhân viên.');
  if (e.employment_status === 'resigned') return fail(409, 'Nhân viên đã nghỉ việc.');
  return out('remind_employee', { employee_id: e.employee_id, full_name: e.full_name });
}

if (action === 'feedback.decide') {
  const f = db.feedback;
  if (!f) return fail(404, 'Không tìm thấy phản hồi.');
  if (f.status !== 'pending_hr') return fail(409, 'Phản hồi ' + f.feedback_id + ' không còn chờ HR duyệt. Vui lòng tải lại trang.');
  const decision = String(b.decision || '');
  if (!['approve', 'decline'].includes(decision)) return fail(400, 'Quyết định không hợp lệ.');
  const message = decision === 'approve' ? 'Đã duyệt và tạo việc hỗ trợ; nhân viên sẽ nhận email về bước tiếp theo.' : 'Đã ghi nhận không tạo việc hỗ trợ cho phản hồi ' + f.feedback_id + '.';
  if (f.wait && f.wait.resume_url) {
    return out('resume', { feedback_id: f.feedback_id, resume_url: f.wait.resume_url, wait_id: f.wait.wait_id,
      field0: decision === 'approve' ? 'Duyệt kế hoạch hỗ trợ' : 'Chưa duyệt / Từ chối', field1: note, message });
  }
  return out('feedback_entry', { feedback_id: f.feedback_id, decision, message });
}

return fail(400, 'Thao tác không hợp lệ.');

parameters.query:
with u as (
  update public.workflow_waits set consumed_at = now() where wait_id = nullif($1, '')::bigint and consumed_at is null returning 1
)
select (select count(*) from u)::int as closed;

insert into public.automation_logs (workflow, entity_id, event, level, message, n8n_execution_id)
values ('WF1', $1, 'candidate_reminded', 'info', $2, $3)
returning log_id;
